import { useEffect, useState } from "react";
import { parsePhoneNumberFromString } from 'libphonenumber-js';
import { CURRENCY_ICONS } from "../Data/Constants";

let ApplicationName = "Checkout";
export default ApplicationName;

export function openPopup(ref, style = 'flex') {
    ref.current.style.display = style;
    setTimeout(() => {
        ref.current.style.bottom = '0%';
    }, 1);
}

export function closePopup(ref) {
    if (ref && ref.current) {
        ref.current.style.bottom = '-110%';
        setTimeout(() => {
            ref.current.style.display = 'none';
        }, 200);
    }
}

export const useSwipeDown = (ref, onSwipeDown, threshold = 50) => {
    const [touchStart, setTouchStart] = useState(null);
    const [touchEnd, setTouchEnd] = useState(null);

    useEffect(() => {
        if (!ref?.current) return;
        const element = ref.current;

        const handleTouchStart = (e) => {
            if (element.scrollTop === 0) {
                setTouchStart(e.touches[0].clientY);
            } else {
                setTouchStart(null);
            }
        };

        const handleTouchMove = (e) => {
            if (touchStart !== null) {
                setTouchEnd(e.touches[0].clientY);

                // Prevent browser pull-to-refresh only when already at the top
                if (element.scrollTop === 0 && touchEnd === null) {
                    e.preventDefault();
                }
            }
        };

        const handleTouchEnd = () => {
            if (touchStart !== null && touchEnd !== null) {
                const swipeDistance = touchEnd - touchStart;
                if (swipeDistance > threshold) {
                    if (onSwipeDown) onSwipeDown();
                }
            }
            setTouchStart(null);
            setTouchEnd(null);
        };

        element.addEventListener("touchstart", handleTouchStart, { passive: false });
        element.addEventListener("touchmove", handleTouchMove, { passive: false });
        element.addEventListener("touchend", handleTouchEnd);

        return () => {
            element.removeEventListener("touchstart", handleTouchStart);
            element.removeEventListener("touchmove", handleTouchMove);
            element.removeEventListener("touchend", handleTouchEnd);
        };
    }, [ref, touchStart, touchEnd, onSwipeDown, threshold]);
};

export function ValidatePhone(number, countryCode) {
    const phoneNumber = parsePhoneNumberFromString(number, countryCode);
    return phoneNumber?.isValid() || false;
}

export function amountInPaisa(number) {
    return (number / 100)?.toFixed(2);
}

export function PrintCurrency(currencyCode, needCurrencySymbol = true) {
    currencyCode = currencyCode?.toUpperCase()
    if (needCurrencySymbol) {
        let sign = CURRENCY_ICONS[currencyCode];
        if (sign) {
            return sign;
        }
        return currencyCode
    } else {
        return currencyCode;
    }
}

export function ProductsParsing(products,rate, setProducts) {
    let items = [];
    products?.forEach((element) => {
        let thisItem = {
            title : element.node.title,
            variant_title: element.node.variant.title,
            variant_id: element.node.variant.id,
            quantity: element.node.quantity,
            image: element.node.variant.image.originalSrc,
            market_price: (parseFloat(element.node.variant.compareAtPriceV2.amount) * rate) * 100,
            price: (parseFloat(element.node.variant.priceV2.amount) * rate) * 100

        }
        items.push(thisItem);
    });
    setProducts(items);
}

export function GetDeviceType() {
    const userAgent = navigator.userAgent || navigator.vendor || window.opera;

    // Check for Android
    if (/android/i.test(userAgent)) {
        return "android";
    }

    // Check for iOS (iPhone or iPad)
    if (/iPad|iPhone|iPod/.test(userAgent) && !window.MSStream) {
        return "ios";
    }

    // Check for Windows
    if (/windows/i.test(userAgent)) {
        return "windows";
    }

    // Check for MacOS
    if (/Macintosh|MacIntel|MacPPC|Mac68K/.test(userAgent)) {
        return "macos";
    }

    // Check for Linux
    if (/linux/i.test(userAgent)) {
        return "linux";
    }

    // Default to unknown
    return "unknown";
}